code='''
    const managedStates=['BUENO','REGULAR','MALO','FUERA DE SERVICIO'];
    function stateOptions(select,value,allowKeep=false){if(allowKeep)select.add(new Option('Conservar estados individuales',''));managedStates.forEach(v=>select.add(new Option(stateLabel(v),v)));select.value=value;}
    async function persist(next){
      validate(next);
      if(!serverInventory){setInventory(next,true);showNotice('Cambios aplicados en esta sesión. Pulsa «Descargar datos» y reemplaza inventario.json para conservarlos.');return;}
      const response=await fetch('guardar.php',{method:'POST',headers:{'Content-Type':'application/json','X-Inventory-Token':saveToken},body:JSON.stringify({inventario:next,revision})});
      const result=await response.json();if(!response.ok)throw new Error(result.error||'No se pudo guardar.');revision=result.revision;setInventory(result.inventario);showNotice('Cambios guardados en inventario.json. Respaldo creado.');
    }
    function openEditor(){editingItem=activeItem;$('edit-fields').replaceChildren();$('edit-error').hidden=true;
      const fields=[['nombre','Nombre'],['categoria','Categoría'],['tipo','Tipo de elemento'],['marca','Marca'],['referencia','Referencia'],['color','Color'],['ubicacion','Ubicación / sede'],['estado','Estado de toda la ficha'],['detalle','Descripción'],['imagenes','Rutas de fotografías (una por línea)']];
      fields.forEach(([key,title])=>{const label=el('label',key==='detalle'||key==='imagenes'?'wide':'',title);let control=el(key==='estado'?'select':key==='detalle'||key==='imagenes'?'textarea':'input');control.id='edit-'+key;control.name=key;if(key==='estado')stateOptions(control,'',true);else control.value=key==='imagenes'?editingItem.imagenes.join('\\n'):editingItem[key]||'';if(['nombre','categoria','tipo'].includes(key))control.required=true;label.append(control);$('edit-fields').append(label);});
      const table=el('table'),head=el('thead'),hrow=el('tr');['ID','Placa','Cantidad','Estado'].forEach(t=>hrow.append(el('th','',t)));head.append(hrow);table.append(head);const body=el('tbody');
      (editingItem.registros?.length?editingItem.registros:[{id:editingItem.id,placa:editingItem.placa,cantidad:editingItem.cantidad,estado:editingItem.estado,fecha_adquisicion:editingItem.fecha_adquisicion}]).forEach((r,index)=>{const row=el('tr');row.dataset.index=index;row.append(el('td','',r.id));['placa','cantidad','estado'].forEach(key=>{const cell=el('td'),control=el(key==='estado'?'select':'input');control.dataset.field=key;if(key==='estado')stateOptions(control,r.estado||editingItem.estado);else{control.value=r[key]??'';if(key==='cantidad'){control.type='number';control.min='1';control.step='1';control.required=true;}}cell.append(control);row.append(cell);});body.append(row);});table.append(body);$('edit-members').replaceChildren(table);$('editor').showModal();
    }
    $('edit-product').addEventListener('click',openEditor);['close-editor','cancel-editor'].forEach(id=>$(id).addEventListener('click',()=>$('editor').close()));
    $('edit-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('save-product');button.disabled=true;$('edit-error').hidden=true;try{const changed=structuredClone(editingItem);['nombre','categoria','tipo','marca','referencia','color','ubicacion','detalle'].forEach(k=>changed[k]=$('edit-'+k).value.trim());changed.imagenes=$('edit-imagenes').value.split(/\\r?\\n/).map(s=>s.trim()).filter(Boolean);
      const originals=changed.registros?.length?changed.registros:[{id:changed.id,fecha_adquisicion:changed.fecha_adquisicion}];changed.registros=[...$('edit-members').querySelectorAll('tbody tr')].map((row,index)=>({...originals[index],placa:row.querySelector('[data-field=placa]').value.trim(),cantidad:Number(row.querySelector('[data-field=cantidad]').value),estado:$('edit-estado').value||row.querySelector('[data-field=estado]').value}));changed.cantidad=changed.registros.reduce((n,r)=>n+r.cantidad,0);const states=[...new Set(changed.registros.map(r=>r.estado))];changed.estado=states.length===1?states[0]:'MIXTO';changed.placa=changed.registros[0].placa;
      const next=structuredClone(inventory);next.equipos=next.equipos.map(i=>String(i.id)===changed.id?changed:i);await persist(next);$('editor').close();openPreview(items.find(i=>i.id===changed.id));}catch(error){$('edit-error').textContent=error.message;$('edit-error').hidden=false;}finally{button.disabled=false;}});
    $('delete-product').addEventListener('click',()=>{deleteItem=activeItem;$('delete-message').textContent=`¿Eliminar «${deleteItem.nombre}» (ID ${deleteItem.id}) y sus ${deleteItem.cantidad} unidades del inventario? Se retirará toda la ficha con sus registros agrupados.`;$('delete-error').hidden=true;$('delete-confirm').showModal();});
    $('cancel-delete').addEventListener('click',()=>$('delete-confirm').close());$('confirm-delete').addEventListener('click',async()=>{const button=$('confirm-delete');button.disabled=true;try{const next=structuredClone(inventory);next.equipos=next.equipos.filter(i=>String(i.id)!==deleteItem.id);await persist(next);$('delete-confirm').close();$('preview').close();}catch(error){$('delete-error').textContent=error.message;$('delete-error').hidden=false;}finally{button.disabled=false;}});
'''
s=s.replace('    async function start()',code+'\n    async function start()')
s=s.replace("const response=await fetch('inventario.json',{cache:'no-cache'});", "const response=await fetch('guardar.php',{cache:'no-cache'});")
